INSERT INTO "public"."product" ("id", "name", "short_description", "description", "price", "sale_price", "discount", "shipping_price", "stock_quantity", "sku", "meta_title", "meta_description", "meta_keywords", "status", "unit", "weight", "is_free_shipping", "created_at", "updated_at", "deleted_at", "thumbnail_id") VALUES
('1693c4c6-3513-4763-9d0e-f303e2307de4', 'น้ำยาประสานท่อพีวีซี 50 กรัม', 'น้ำยาประสานท่อพีวีซี (ชนิดใส) กาวทาท่อ SCG  ขนาด 50 กรัม รุ่นไม่มีแปรง
ชนิดใส ประเภทรับแรงดันทั่วไป', '<ul><li>ส่วนประกอบ -เมทิลเอทิลคีโทน 36% ,ไซโคลเฮกซาโนน 24% ,สารระเหยอื่นๆ 20% ,สารบรรจุแต่งอื่นๆ 20%</li><li>&nbsp;วิธีใช้ 1.ตัดท่อตามที่ต้องการ ใช้ตะไบลบปลายท่อประมาณ 15 องศา และทำความสะอาด&nbsp;</li><li>2.ใช้แปรงสะอาด ทาน้ำยาประสานท่อที่ผิวด้านนอกท่อและด้านในข้อต่อ สวมท่อกับข้อต่อเข้าด้วยกัน จับนิ่งๆไว้ 10-15 วินาที 3.เช็ดน้ำยาส่วนเกินออก ทิ้งไว้ประมาณ 20-30 นาที ก่อนใช้งาน อายุการเก็บรักษา</li><li>&nbsp;-ควรใช้ภายใน 18 เดือน นับจากวันผลิต ดูใต้กระป๋อง&nbsp;</li></ul>', 45, 45, NULL, 0, 6, '1', '', '', NULL, 'ACTIVE', '1 ชิ้น ', 15, 'f', '2024-04-19 07:30:03.438832', '2024-08-25 12:45:03.198203', NULL, '2f78068b-8ae3-4cb3-84f3-3629b3d9e43e'),
('29204165-051e-45a6-ae3b-08ee5a0955a6', 'น้ำยาประสานท่อพีวีซี  250 กรัม', 'น้ำยาประสานท่อพีวีซี (ชนิดใส) ขนาด 250 กรัม รุ่นไม่มีแปรง
ชนิดใส ประเภทรับแรงดันทั่วไป', '<p>น้ำยาประสานท่อพีวีซี</p><p>ส่วนประกอบ</p><p>&nbsp;-เมทิลเอทิลคีโทน 36% ,ไซโคลเฮกซาโนน 24% ,สารระเหยอื่นๆ 20% ,สารบรรจุแต่งอื่นๆ 20%&nbsp;</p><p>วิธีใช้</p><p>&nbsp;1.ตัดท่อตามที่ต้องการ ใช้ตะไบลบปลายท่อประมาณ 15 องศา และทำความสะอาด&nbsp;</p><p>2.ใช้แปรงสะอาด ทาน้ำยาประสานท่อที่ผิวด้านนอกท่อและด้านในข้อต่อ สวมท่อกับข้อต่อเข้าด้วยกัน จับนิ่งๆไว้ 10-15 วินาที 3.เช็ดน้ำยาส่วนเกินออก ทิ้งไว้ประมาณ 20-30 นาที</p><p>&nbsp;ก่อนใช้งาน อายุการเก็บรักษา -ควรใช้ภายใน 18 เดือน นับจากวันผลิต ดูใต้กระป๋อง&nbsp;</p><p>คำเตือน</p><p>&nbsp;1.โปรดอ่านวิธีใช้ก่อนใช้งาน</p><p>&nbsp;2.ควรสวมถุงมือ ผ้าปิดจมูก และแว่นตาทุกครั้งเมื่อใช้งาน 3.ระวังอย่าสูดดม อย่าให้ถูกผิวหนังหรือเข้าตา&nbsp;</p><p>4.หากได้รับอันตรายโปรดพบแพทย์ทันที</p><p>&nbsp;5.ใช้เพื่อประสานท่อพีวีซีและข้อต่อพีวีซีชนิดแข็งเท่านั้น</p><p>&nbsp;6.ใช้ร่วมกับอุปกรณ์มาตรฐานเท่านั้น&nbsp;</p><p>7.น้ำยาที่บรรจุนำไปใช้งานได้ทันทีโดยไม่ต้องผสมสารอื่นๆ เพิ่มเติม</p><p>&nbsp;8.ปิดฝาให้สนิทหลังการใช้งานทุครั้ง&nbsp;</p><p>9.ควรเก็บในที่ร่ม มีอากาศถ่ายเท ห่างจากเปลวไฟ และควรเก็บให้พ้นมือเด็ก</p><p>&nbsp;10.ห้ามนำภาชนะไปเผาไฟหรือทำลายรวมกับขยะชนิดอื่น</p><p>&nbsp;การปฐมพยาบาลเบื้องต้นก่อนพาไปพบแพทย์&nbsp;</p><p>-กรณีสูดดม : เคลื่อนย้ายผู้ป่วยไปที่อากาศบริสุทธิ์</p><p>&nbsp;-กรณีสัมผัสผิวหนัง : ถอดเสื้อผ้าหรืออุปกรณ์ที่เปรอะเปื้อนออก ล้างด้วยน้ำปริมาณมากๆ อย่างน้อย 15 นาทีบริเวณที่สัมผัสผิวหนัง</p><p>&nbsp;-กรณีสัมผัสดวงตา : ล้างตาด้วยน้ำสะอาดให้มากที่สุดทันที โดยเปิดเปลือกตาขึ้นให้น้ำไหลผ่านตาอย่างน้อย 15 นาที ห้ามขยี้ตา</p>', 155, 155, NULL, 0, 5, '1', '', '', NULL, 'ACTIVE', '1 ชิ้น ', 15, 'f', '2024-04-19 07:52:09.893472', '2024-08-25 12:42:03.716837', NULL, '2e874854-e8a1-440c-88c9-81a856c5e182'),
('4487e3a0-4e47-4361-bf5b-4e36032620f0', 'น้ำยาประสานท่อพีวีซี  500 กรัม', 'น้ำยาประสานท่อพีวีซี (ชนิดใส)  ขนาด 500 กรัม รุ่นไม่มีแปรง ชนิดใส ประเภทรับแรงดันทั่วไป', '<ul><li>น้ำยาประสานท่อพีวีซี &nbsp;</li><li>ส่วนประกอบ -เมทิลเอทิลคีโทน 36% ,ไซโคลเฮกซาโนน 24% ,สารระเหยอื่นๆ 20% ,สารบรรจุแต่งอื่นๆ 20%</li><li>&nbsp;วิธีใช้ 1.ตัดท่อตามที่ต้องการ ใช้ตะไบลบปลายท่อประมาณ 15 องศา และทำความสะอาด&nbsp;</li><li>2.ใช้แปรงสะอาด ทาน้ำยาประสานท่อที่ผิวด้านนอกท่อและด้านในข้อต่อ สวมท่อกับข้อต่อเข้าด้วยกัน จับนิ่งๆไว้ 10-15 วินาที 3.เช็ดน้ำยาส่วนเกินออก ทิ้งไว้ประมาณ 20-30 นาที</li><li>&nbsp;ก่อนใช้งาน อายุการเก็บรักษา -ควรใช้ภายใน 18 เดือน นับจากวันผลิต ดูใต้กระป๋อง</li><li>&nbsp;คำเตือน</li><li>&nbsp;1.โปรดอ่านวิธีใช้ก่อนใช้งาน</li><li>&nbsp;2.ควรสวมถุงมือ ผ้าปิดจมูก และแว่นตาทุกครั้งเมื่อใช้งาน 3.ระวังอย่าสูดดม อย่าให้ถูกผิวหนังหรือเข้าตา</li><li>&nbsp;4.หากได้รับอันตรายโปรดพบแพทย์ทันที</li><li>&nbsp;5.ใช้เพื่อประสานท่อพีวีซีและข้อต่อพีวีซีชนิดแข็งเท่านั้น</li><li>&nbsp;6.ใช้ร่วมกับอุปกรณ์มาตรฐานเท่านั้น</li><li>&nbsp;7.น้ำยาที่บรรจุนำไปใช้งานได้ทันทีโดยไม่ต้องผสมสารอื่นๆ เพิ่มเติม&nbsp;</li><li>8.ปิดฝาให้สนิทหลังการใช้งานทุครั้ง</li><li>&nbsp;9.ควรเก็บในที่ร่ม มีอากาศถ่ายเท ห่างจากเปลวไฟ และควรเก็บให้พ้นมือเด็ก&nbsp;</li><li>10.ห้ามนำภาชนะไปเผาไฟหรือทำลายรวมกับขยะชนิดอื่น&nbsp;</li><li>การปฐมพยาบาลเบื้องต้นก่อนพาไปพบแพทย์</li><li>-กรณีสูดดม : เคลื่อนย้ายผู้ป่วยไปที่อากาศบริสุทธิ์</li><li>-กรณีสัมผัสผิวหนัง : ถอดเสื้อผ้าหรืออุปกรณ์ที่เปรอะเปื้อนออก ล้างด้วยน้ำปริมาณมากๆ อย่างน้อย 15 นาทีบริเวณที่สัมผัสผิวหนัง&nbsp;</li><li>-กรณีสัมผัสดวงตา : ล้างตาด้วยน้ำสะอาดให้มากที่สุดทันที โดยเปิดเปลือกตาขึ้นให้น้ำไหลผ่านตาอย่างน้อย 15 นาที ห้ามขยี้ตา</li></ul>', 290, 290, NULL, -3, 4, '1', '', '', NULL, 'ACTIVE', '1 ชิ้น ', 15, 'f', '2024-04-19 08:02:14.476239', '2024-08-25 12:40:28.520706', NULL, 'd6edf3cc-b83e-465c-931b-ec7e06e449f0'),
('4914172b-1a37-4219-b057-9835d50adb3e', 'ก๊อกบอลแฟนซีสนาม 1/2 นิ้วSANWA ', 'ก๊อกบอลแฟนซีสนาม 1/2 นิ้วSANWA 
 ตัวเรือนและลูกบอลวาล์วทำจากทองเหลือง ทำให้ภายในที่สัมผัสน้ำปลอดสนิม 
', '<p>จุดเด่นของ ก๊อกบอลแฟนซี SANWA 1. ตัวเรือนเล็กกะทัดรัด ราคาคุ้มค่า 2. ด้ามจับดีไซน์เฉพาะ สีสวย จับถนัดมือ ทนทานต่อการเปิด-ปิด ได้ 20,000 ครั้ง 3. ป้องกันการรั่วซึมถึง 2 ชั้น ด้วย Double O-ring (จุดแกนบังคับลูกบอล) 4. ตกแต่งเพื่อความสวยงาม เข้ากับกระเบื้อง 5. เหมาะกับงานอาคาร ที่พักอาศัย ร้านอาหาร พื้นที่ส่วนระเบียง 6. ใช้ในพื้นที่แคบ เช่น ระเบียง</p>', 95, 95, NULL, 34, 6, '1', '', '', NULL, 'ACTIVE', '1 ชิ้น ', 10, 'f', '2024-04-19 03:28:42.241553', '2024-08-25 12:49:18.73052', NULL, 'c73bcbb6-9707-4575-a5fb-9f5ef8f4e957'),
('639776c2-c486-4d2a-ba9c-cdb23da29a11', 'ข้อต่อ 1 นิ้ว', 'ข้อต่อ 1 นิ้ว SCG ข้อต่อ 1 นิ้ว SCG ข้อต่อตรง PVC คุณภาพจากแบรนด์ SCG สำหรับงานระบบน้ำประปาทั่วไป ผลิตจาก Rigid PVC เป็นพลาสติก PVC แข็งที่มีคุณภาพ ทนทาน ไม่แตกหักง่าย คงทนต่อสภาวะอากาศความชื้น ไม่เป็นสนิม ไม่ลามไฟ ทนต่อแรงดันน้ำได้เป็นอย่างดี', '<p>ข้อต่อตรง PVC สำหรับงานเดินท่อประปาทั่วไป</p><ol><li>ผลิตจาก Rigid PVC เป็นพลาสติก PVC แข็งที่มีคุณภาพ เนื้อพลาสติกเหนียวทนทาน</li><li>วัสดุเป็นฉนวนไฟฟ้า มีคุณสมบัติไม่ลามไฟ ทนต่อสภาพกรด-ด่าง แสงแดด และความชื้น</li><li>ใช้งานร่วมกับท่อ PVC ขนาดเส้นผ่านศูนย์กลาง 1 นิ้ว</li><li>ทนต่อแรงดันน้ำได้สูงสุด 13.5 บาร์</li></ol><ul><li>ขนาด 1 นิ้ว</li><li>สีฟ้า</li></ul>', 45, 45, NULL, 5, 10, '1', '', '', NULL, 'ACTIVE', '1 ชิ้น', 15, 'f', '2024-04-05 07:34:31.332748', '2024-08-25 12:49:50.390761', NULL, 'e9a29c89-0859-467a-ae86-d4f4864ebfe9'),
('91db07a9-8f94-4cc0-a952-6d46c379374c', 'ก๊อกบอลสนาม 1/2" SANWA', ' ก๊อกน้ำทองเหลืองชุบแท้คุณภาพ ผ่านมาตรฐาน ของแท้ไม่เป็นสนิม', '<ul><li>คุณสมบัติ</li><li>-ตัวก๊อกทำจากทองเหลืองคุณภาพสูง โดยวิธีปั๊มร้อนขึ้นรูป ชุบนิเกิ้ลโครเมี่ยมเพิ่มความสวยงามทนทาน</li><li>- ใช้วัสดุเทฟล่อนคุณภาพสูงในการผลิตแหวนรองรับลูกบอล&nbsp;</li><li>- ป้องกันการรั่วซึมและเพิ่มความนุ่มนวลในการเปิด-ปิด ลูกบอล -การบังคับทางไหลของน้ำทำจากทองเหลืองคุณภาพสูงปราศจากการเกิดสนิม ทำให้การเปิด-ปิดเป็นไปโดยสะดวก ไม่เกิดการติดขัด&nbsp;</li><li>-ด้ามจับทำจากอลูมิเนียม รูปทรงกะทัดรัด จับถนัดมือ&nbsp;</li><li>- ก๊อกบอลทุกชิ้นผ่านการทดสอบการรั่วซึมก่อนออกจำหน่าย&nbsp;<br>&nbsp;</li></ul>', 110, 110, NULL, 5, 6, 'ก๊อกบอลสนาม ', '', '', NULL, 'ACTIVE', '1 ชิ้น ', 15, 'f', '2024-04-18 09:34:32.146084', '2024-08-25 12:49:33.804178', NULL, 'a62e367e-71cc-4a73-96e4-9e09a52d958c'),
('9550659a-c69d-47ae-9226-e7ed756bbc01', 'บอลวาล์ว PVC ขนาด3นิ้ว', 'บอลวาล์ว 3 นิ้ว ใช้ได้กับงานท่อพีวีซีทั่วไป', '<ul><li>-ผ่านการตรวจสอบคุณภาพมาตรฐานทุกตัว</li><li>&nbsp;- ติดตั้งง่าย และสะดวกในการโยกย้าย&nbsp;</li><li>- รับความดันได้ถึง 150 PSI</li><li>&nbsp;-เหมาะสำหรับการใช้ในอุตสาหกรรมทั่วไป​และการเกษตร</li><li>&nbsp;-ใช้สำหรับต่อกับอุปกรณ์และท่อเพื่อเปิด-ปิดน้ำ</li><li>-ใช้ได้ทั้งน้ำประปา​ น้ำเค็ม​ น้ำมันและของเหลวอื่นๆ</li><li>&nbsp;-คุณภาพคงทน​ อายุการใช้งานยาวนาน​ ราคาไม่แพง</li></ul>', 670, 670, NULL, 0, 10, '1', '', '', NULL, 'ACTIVE', '1 ชิ้น ', 15, 'f', '2024-04-19 04:47:08.942671', '2024-08-25 12:46:06.203341', NULL, '7cd3b9bd-299f-4339-aad4-f3b1f5d40683'),
('a41d9346-8a7e-4cbe-9685-f9619deb4810', 'บอลวาล์วพีวีซี 1/2 นิ้ว', 'พีวีซีแข็ง (Rigid PVC) ซึ่งปัจจุบันเป็นที่นิยมใช้งานการก่อสร้าง', '<p>ผลิตภัณฑ์ uPVC (Unplasticized Polyvinyl Chloride) หรือ พีวีซีแข็ง (Rigid PVC) ซึ่งปัจจุบันเป็นที่นิยมใช้งานการก่อสร้าง เนื่องจากมีคุณสมบัติที่โดดเด่นหลายประการ อาทิ คงทนต่อสภาวะอากาศความชื้น ไม่เป็นสนิม ไม่ลามไฟ รวมถึงไม่ต้องบำรุงรักษามากนัก&nbsp;</p><p>- ทนทานต่อแรงดันและแรงกด</p><p>&nbsp;- ทนต่อสภาพกรดด่าง</p><p>&nbsp;- ปลอดภัยจากสารพิษ&nbsp;</p><p>- เป็นฉนวนไฟฟ้า</p><p>&nbsp;- ทนทานต่อแสงแดด&nbsp;</p><p>- น้ำหนักเบา</p>', 35, 35, NULL, 35, 12, '1', '', '', NULL, 'ACTIVE', '1 ชิ้น', 15, 'f', '2024-04-19 04:06:58.74682', '2024-08-25 12:52:35.144497', NULL, 'ba3af054-3ff2-4280-a2e2-ec18c2c7ce1d'),
('a8d90e99-c9de-40d7-a889-cf2b8b747f0e', 'บอลวาล์วพีวีซี 3/4 นิ้ว ', 'พีวีซีแข็ง (Rigid PVC) ซึ่งปัจจุบันเป็นที่นิยมใช้งานการก่อสร้าง', '<p>ผลิตภัณฑ์ uPVC (Unplasticized Polyvinyl Chloride) หรือ พีวีซีแข็ง (Rigid PVC) ซึ่งปัจจุบันเป็นที่นิยมใช้งานการก่อสร้าง เนื่องจากมีคุณสมบัติที่โดดเด่นหลายประการ อาทิ คงทนต่อสภาวะอากาศความชื้น ไม่เป็นสนิม ไม่ลามไฟ รวมถึงไม่ต้องบำรุงรักษามากนัก<br>- ทนทานต่อแรงดันและแรงกด<br>- ทนต่อสภาพกรดด่าง<br>- ปลอดภัยจากสารพิษ<br>- เป็นฉนวนไฟฟ้า<br>- ทนทานต่อแสงแดด<br>- น้ำหนักเบา</p>', 48, 48, NULL, 0, 12, '1', '', '', NULL, 'ACTIVE', '1 ชิ้น', 15, 'f', '2024-04-19 04:29:25.830603', '2024-08-25 12:46:36.903726', NULL, 'e234d1e6-8a48-44a0-a856-b66547b44fb4'),
('ce119ae5-67e0-40ba-afec-34e0dfd45bd0', 'บอลวาล์ว PVC ขนาด2นิ้ว', 'บอลวาล์ว PVC ขนาด2นิ้ว(2”) พีวีซี 55 มม. ตราช้าง เอสซีจี SCG คุณภาพดีมาก', '<ul><li>-บอลวาล์ว PVC แบบสวม ตราช้าง</li><li>&nbsp;-ทนต่อสภาพกรด-ด่าง และเป็นฉนวนไฟฟ้า</li><li>&nbsp;-น้ำหนักเบา&nbsp;</li><li>-รับความดันได้ถึง 150 psi&nbsp;</li><li>-ผลิตจากพลาสติกคุณภาพได้มาตรฐาน&nbsp;</li><li>-ผลิตภัณฑ์ uPVC Unplasticized Polyvinyl Chloride หรือ พีวีซีแข็ง Rigid PVC ซึ่งปัจจุบันเป็นที่นิยมใช้ในการก่อสร้างเนื่องจากมีคุณสมบัติเด่นหลายประการ ทนชื้น ไม่ลามไฟ ปลอดสารพิษ -สินค้าทุกชิ้นผ่านการทดสอบการรั่วซึมและแรงดัน&nbsp;</li><li>-มีอายุการใช้งานที่ยาวนาน</li><li>&nbsp;-ห้ามใช้กับน้ำอุณหภูมิเกิน 60 องศา เพราะอาจจะทำให้เสียรูปทรงและเกิดการรั่วซึมได้&nbsp;</li><li>-มอก. 17-2532 สีฟ้า ท่อรับแรงดัน ท่อระบายน้ำทิ้ง และสิ่งปฏิกูล</li><li>&nbsp;-เปิดปิด และติดตั้งเองได้ง่าย&nbsp;</li><li>-1กล่องใหญ่ บรรจุ 24 ตัว</li><li>&nbsp;-ราคาสินค้าอาจมีการเปลี่ยนแปลงโดยไม่แจ้งให้ทราบล่วงหน้า</li></ul>', 205, 205, NULL, 0, 12, '1', '', '', NULL, 'ACTIVE', '1ชิ้น', 15, 'f', '2024-04-19 04:42:30.601355', '2024-08-25 12:46:23.024775', NULL, 'a66a8d74-6641-4c00-88db-12601996afb9'),
('d9a5fff5-7690-4634-badc-3e5c839a53ef', 'น้ำยาประสานท่อพีวีซี 100 กรัม', 'น้ำยาประสานท่อพีวีซี 100 กรัม รุ่นไม่มีแปรง
ชนิดใส ประเภทรับแรงดันทั่วไป', '<ul><li>ส่วนประกอบ -เมทิลเอทิลคีโทน 36% ,ไซโคลเฮกซาโนน 24% ,สารระเหยอื่นๆ 20% ,สารบรรจุแต่งอื่นๆ 20%</li><li>&nbsp;วิธีใช้</li><li>&nbsp;1.ตัดท่อตามที่ต้องการ ใช้ตะไบลบปลายท่อประมาณ 15 องศา และทำความสะอาด&nbsp;</li><li>2.ใช้แปรงสะอาด ทาน้ำยาประสานท่อที่ผิวด้านนอกท่อและด้านในข้อต่อ สวมท่อกับข้อต่อเข้าด้วยกัน จับนิ่งๆไว้ 10-15 วินาที 3.เช็ดน้ำยาส่วนเกินออก ทิ้งไว้ประมาณ 20-30 นาที ก่อนใช้งาน อายุการเก็บรักษา&nbsp;</li><li>-ควรใช้ภายใน 18 เดือน นับจากวันผลิต ดูใต้กระป๋อง&nbsp;</li><li>คำเตือน 1.โปรดอ่านวิธีใช้ก่อนใช้งาน</li><li>&nbsp;2.ควรสวมถุงมือ ผ้าปิดจมูก และแว่นตาทุกครั้งเมื่อใช้งาน 3.ระวังอย่าสูดดม อย่าให้ถูกผิวหนังหรือเข้าตา</li><li>&nbsp;4.หากได้รับอันตรายโปรดพบแพทย์ทันที</li><li>&nbsp;5.ใช้เพื่อประสานท่อพีวีซีและข้อต่อพีวีซีชนิดแข็งเท่านั้น</li><li>&nbsp;6.ใช้ร่วมกับอุปกรณ์มาตรฐานเท่านั้น&nbsp;</li><li>7.น้ำยาที่บรรจุนำไปใช้งานได้ทันทีโดยไม่ต้องผสมสารอื่นๆ เพิ่มเติม&nbsp;</li><li>8.ปิดฝาให้สนิทหลังการใช้งานทุครั้ง</li><li>&nbsp;9.ควรเก็บในที่ร่ม มีอากาศถ่ายเท ห่างจากเปลวไฟ และควรเก็บให้พ้นมือเด็ก</li><li>&nbsp;10.ห้ามนำภาชนะไปเผาไฟหรือทำลายรวมกับขยะชนิดอื่น</li><li>&nbsp;การปฐมพยาบาลเบื้องต้นก่อนพาไปพบแพทย์</li><li>&nbsp;-กรณีสูดดม : เคลื่อนย้ายผู้ป่วยไปที่อากาศบริสุทธิ์&nbsp;</li><li>-กรณีสัมผัสผิวหนัง : ถอดเสื้อผ้าหรืออุปกรณ์ที่เปรอะเปื้อนออก ล้างด้วยน้ำปริมาณมากๆ อย่างน้อย 15 นาทีบริเวณที่สัมผัสผิวหนัง -</li><li>กรณีสัมผัสดวงตา : ล้างตาด้วยน้ำสะอาดให้มากที่สุดทันที โดยเปิดเปลือกตาขึ้นให้น้ำไหลผ่านตาอย่างน้อย 15 นาที ห้ามขยี้ตา</li></ul>', 70, 70, NULL, 32, 5, '1', '', '', NULL, 'ACTIVE', '1 ชิ้น ', 15, 'f', '2024-04-19 07:40:38.558522', '2024-08-25 12:42:45.670168', NULL, 'fcae73db-98c9-4f8b-a35c-2661b9290a1a'),
('fc2c2269-02d4-4561-bd3b-1f30dfcde7a7', 'บอลวาล์วพีวีซี  1 นิ้ว ', 'พีวีซีแข็ง (Rigid PVC) ซึ่งปัจจุบันเป็นที่นิยมใช้งานการก่อสร้าง', '<ul><li>ผลิตภัณฑ์ uPVC (Unplasticized Polyvinyl Chloride) หรือ พีวีซีแข็ง (Rigid PVC) ซึ่งปัจจุบันเป็นที่นิยมใช้งานการก่อสร้าง เนื่องจากมีคุณสมบัติที่โดดเด่นหลายประการ อาทิ คงทนต่อสภาวะอากาศความชื้น ไม่เป็นสนิม ไม่ลามไฟ รวมถึงไม่ต้องบำรุงรักษามากนัก</li><li>&nbsp;- ทนทานต่อแรงดันและแรงกด</li><li>&nbsp;- ทนต่อสภาพกรดด่าง</li><li>&nbsp;- ปลอดภัยจากสารพิษ</li><li>&nbsp;- เป็นฉนวนไฟฟ้า</li><li>&nbsp;- ทนทานต่อแสงแดด</li><li>&nbsp;- น้ำหนักเบา</li></ul>', 70, 70, NULL, 0, 12, '1 ', '', '', NULL, 'ACTIVE', '1 ชิ้น ', 15, 'f', '2024-04-19 04:14:55.157153', '2024-08-25 12:48:31.071301', NULL, 'a66a8d74-6641-4c00-88db-12601996afb9'),
('fc36590c-fdce-47bb-be7d-51b47ced4d3e', 'เทปพันเกลียว', 'เทปพันเกลียว (​SCG) สำหรับพันเกลียวทองเหลืองและพีวีซี สำหรับงานระบบประปา-ระบายน้ำ', '<ul><li>ความยาว: 10 เมตร / ม้วน ความกว้าง: 12 มิลลิเมตร คำแนะนำ: ก่อนใช้งาน ควรทำความสะอาดพื้นผิวให้แห้ง สะอาดปราศจากเศษขี้ฝุ่นและคราบไขมัน</li><li>คุณสมบัติ ผลิตจากวัตถุดิบ PTFE 100% คุณภาพสูง เนื้อเทปหนาเป็นพิเศษ สามารถใช้ได้ในอุณหภูมิ -190 C ถึง 370 C มีความเหนียวและยืดหยุ่นสูง ทนต่อสารทำละลายและแรงเสียดทานได้ดี</li></ul>', 25, 25, NULL, 0, 24, '1', '', '', NULL, 'ACTIVE', '1 ชิ้น ', 15, 'f', '2024-04-19 06:52:29.996755', '2024-08-25 12:54:05.088402', NULL, '45f94dfd-4b1d-4257-b3e4-7215f205685f');
